const input = $input.first().json;
const headers = input.headers ?? {};
const body = input.body ?? {};
const authorization = headers.authorization ?? headers.Authorization;
if (!authorization?.startsWith('Bearer ')) throw new Error('A valid Quantura Bearer token is required.');
if (!body.dataset_id) throw new Error('dataset_id is required.');
if (!String(body.question ?? '').trim()) throw new Error('question is required.');
return [{ json: { authorization, dataset_id: String(body.dataset_id), question: String(body.question).trim().slice(0, 2000), confirm: body.confirm === true, confirmation_id: body.confirmation_id ? String(body.confirmation_id) : null } }];

const answer = $input.first().json;
const request = $('Validate Cleaning Request').first().json;
const proposal = answer.proposed_transformation ?? null;
const endpointByAction = { deduplicate: '/clean/deduplicate', impute: '/clean/impute' };
const endpoint = proposal ? endpointByAction[proposal.action] : null;
const confirmationId = proposal ? `${request.dataset_id}:${proposal.action}:${proposal.preview_affected_rows}` : null;
const confirmationMatches = !request.confirmation_id || request.confirmation_id === confirmationId;
const shouldExecute = Boolean(request.confirm && proposal && endpoint && confirmationMatches);
return [{ json: { should_execute: shouldExecute, dataset_id: request.dataset_id, authorization: request.authorization, answer: answer.answer, evidence: answer.evidence_summary ?? null, proposal, endpoint, payload: proposal?.operation_payload ?? null, confirmation_id: confirmationId, requires_confirmation: Boolean(proposal) && !shouldExecute, unsupported_action: Boolean(proposal) && !endpoint, error: request.confirm && !confirmationMatches ? 'The confirmation ID does not match the current cleaning proposal.' : null } }];
